<?php require __DIR__.'/inc/header.php';$title='Users & Permissions';$pdo=db();$permKeys=['products','orders','inventory','content','reviews','contacts','media','settings'];if(is_post()){verify_csrf();$id=(int)post('id');$role=(string)post('role','customer');$per=[];foreach($permKeys as $k)if(post('perm_'.$k))$per[$k]=1;$pdo->prepare('UPDATE users SET role=?,permissions=? WHERE id=?')->execute([$role,json_encode($per),$id]);flash('success','User permissions updated.');redirect('/admin/users.php');}$users=$pdo->query("SELECT id,name,email,phone,role,status,permissions FROM users ORDER BY id DESC")->fetchAll();?><div class="bg-white border rounded-2xl overflow-hidden soft"><div class="p-5 font-black">Management Users</div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">User</th><th class="p-3">Role</th><th class="p-3">Permissions</th><th class="p-3"></th></tr></thead><tbody><?php foreach($users as $u):$up=json_decode($u['permissions']??'',true)?:[];?><tr class="border-t"><td class="p-3"><b><?=e($u['name'])?></b><div class="text-xs text-slate-400"><?=e($u['email'])?></div></td><td class="p-3"><?=e($u['role'])?></td><td class="p-3"><div class="flex flex-wrap gap-1"><?php foreach($permKeys as $k): if(!empty($up[$k])):?><span class="text-[10px] bg-slate-100 px-2 py-1 rounded-full"><?=e($k)?></span><?php endif;endforeach;?></div></td><td class="p-3"><details><summary class="cursor-pointer font-bold text-blue-600">Manage</summary><form method="post" class="mt-3 p-3 rounded-xl bg-slate-50 space-y-2"><?=csrf_input()?><input type="hidden" name="id" value="<?=$u['id']?>"><select name="role" class="w-full rounded-lg border-slate-200"><option>customer</option><option>editor</option><option>manager</option><option>admin</option></select><div class="grid grid-cols-2 gap-2"><?php foreach($permKeys as $k):?><label class="text-xs"><input type="checkbox" name="perm_<?=$k?>" <?=!empty($up[$k])?'checked':''?>> <?=e($k)?></label><?php endforeach;?></div><button class="px-3 py-2 bg-slate-950 text-white rounded-lg text-xs font-bold">Save</button></form></details></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/inc/footer.php'; ?>
